//! `sliver-emoji`: the data behind the emoji picker.
//!
//! * [`all`]: every fully-qualified emoji of the Unicode set in CLDR order with its name and
//!   [`Group`]. Skin-tone variants aren't separate entries: an emoji that has them lists its five
//!   single-tone variants in [`Emoji::tones`], and [`family`] maps any variant back to its base. The table is `data/emoji.tsv`, generated by `tools/gen.py` from
//!   Unicode's `emoji-test.txt` and compiled in (about 64 KiB).
//! * [`search`]: a word-prefix match over names.
//! * [`Recents`]: the last emoji used, optionally persisted to a small text file.
//!
//! How a chosen emoji is typed into the focused app is the agent's job (`wtype`, or `wl-copy`
//! plus Ctrl+V); see `docs/customization.md` for the `emoji` module.

use std::path::{Path, PathBuf};
use std::sync::OnceLock;

const DATA: &str = include_str!("../data/emoji.tsv");

/// Unicode's emoji groups, in picker order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Group {
    Smileys,
    People,
    Animals,
    Food,
    Travel,
    Activities,
    Objects,
    Symbols,
    Flags,
}

impl Group {
    pub const ALL: [Group; 9] = [
        Group::Smileys,
        Group::People,
        Group::Animals,
        Group::Food,
        Group::Travel,
        Group::Activities,
        Group::Objects,
        Group::Symbols,
        Group::Flags,
    ];

    fn parse(s: &str) -> Option<Group> {
        Some(match s {
            "Smileys & Emotion" => Group::Smileys,
            "People & Body" => Group::People,
            "Animals & Nature" => Group::Animals,
            "Food & Drink" => Group::Food,
            "Travel & Places" => Group::Travel,
            "Activities" => Group::Activities,
            "Objects" => Group::Objects,
            "Symbols" => Group::Symbols,
            "Flags" => Group::Flags,
            _ => return None,
        })
    }

    pub fn name(self) -> &'static str {
        match self {
            Group::Smileys => "Smileys & Emotion",
            Group::People => "People & Body",
            Group::Animals => "Animals & Nature",
            Group::Food => "Food & Drink",
            Group::Travel => "Travel & Places",
            Group::Activities => "Activities",
            Group::Objects => "Objects",
            Group::Symbols => "Symbols",
            Group::Flags => "Flags",
        }
    }

    /// An emoji that stands for the group on a tab.
    pub fn icon(self) -> &'static str {
        match self {
            Group::Smileys => "😀",
            Group::People => "👋",
            Group::Animals => "🐶",
            Group::Food => "🍔",
            Group::Travel => "🚗",
            Group::Activities => "⚽",
            Group::Objects => "💡",
            Group::Symbols => "🔣",
            Group::Flags => "🏳",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Emoji {
    /// The text to type (may be several code points: ZWJ sequences, flags).
    pub text: &'static str,
    pub name: &'static str,
    pub group: Group,
    /// The five single skin-tone variants, light to dark, when this emoji has them.
    pub tones: Option<[&'static str; 5]>,
}

/// Every emoji, in CLDR order.
pub fn all() -> &'static [Emoji] {
    static ALL: OnceLock<Vec<Emoji>> = OnceLock::new();
    ALL.get_or_init(|| {
        DATA.lines()
            .filter_map(|l| {
                let mut it = l.split('\t');
                let (text, name, group) = (it.next()?, it.next()?, Group::parse(it.next()?)?);
                let tones = it.next().and_then(|t| {
                    let v: Vec<&'static str> = t.split(' ').collect();
                    v.try_into().ok()
                });
                Some(Emoji {
                    text,
                    name,
                    group,
                    tones,
                })
            })
            .collect()
    })
}

/// The emoji `text` belongs to: itself, or the base of a skin-tone variant (`👍🏽` → `👍`).
pub fn family(text: &str) -> Option<&'static Emoji> {
    static BY_TEXT: OnceLock<std::collections::HashMap<&'static str, usize>> = OnceLock::new();
    let map = BY_TEXT.get_or_init(|| {
        let mut m = std::collections::HashMap::new();
        for (i, e) in all().iter().enumerate() {
            m.insert(e.text, i);
            for t in e.tones.iter().flatten() {
                m.insert(*t, i);
            }
        }
        m
    });
    map.get(text).map(|&i| &all()[i])
}

pub fn in_group(g: Group) -> impl Iterator<Item = &'static Emoji> {
    all().iter().filter(move |e| e.group == g)
}

/// Emoji whose name has every query word as a word prefix (`"face tear"` finds
/// "face with tears of joy"), best matches (exact word) first, at most `limit`.
pub fn search(query: &str, limit: usize) -> Vec<&'static Emoji> {
    let words: Vec<String> = query.split_whitespace().map(str::to_lowercase).collect();
    if words.is_empty() {
        return Vec::new();
    }
    let mut hits: Vec<(usize, &Emoji)> = all()
        .iter()
        .filter_map(|e| {
            let name = e.name.to_lowercase();
            let toks: Vec<&str> = name
                .split(|c: char| !c.is_alphanumeric())
                .filter(|t| !t.is_empty())
                .collect();
            let mut score = 0;
            for w in &words {
                if toks.iter().any(|t| t == w) {
                    // exact word: best
                } else if toks.iter().any(|t| t.starts_with(w.as_str())) {
                    score += 1;
                } else {
                    return None;
                }
            }
            Some((score, e))
        })
        .collect();
    hits.sort_by_key(|(s, _)| *s);
    hits.into_iter().take(limit).map(|(_, e)| e).collect()
}

/// The most recently used emoji, newest first.
#[derive(Debug, Clone, Default)]
pub struct Recents {
    items: Vec<String>,
    path: Option<PathBuf>,
}

/// How many recents are kept.
pub const MAX_RECENTS: usize = 24;

impl Recents {
    /// In memory only.
    pub fn new() -> Recents {
        Recents::default()
    }

    /// Persisted at `path` (one emoji per line); loads what is there.
    pub fn at(path: impl Into<PathBuf>) -> Recents {
        let path = path.into();
        let items = std::fs::read_to_string(&path)
            .map(|t| {
                t.lines()
                    .filter(|l| !l.is_empty())
                    .take(MAX_RECENTS)
                    .map(str::to_string)
                    .collect()
            })
            .unwrap_or_default();
        Recents {
            items,
            path: Some(path),
        }
    }

    /// `$XDG_STATE_HOME/sliver/emoji-recents` (or `~/.local/state/...`).
    pub fn default_path(get: impl Fn(&str) -> Option<String>) -> Option<PathBuf> {
        let base = get("XDG_STATE_HOME")
            .filter(|s| !s.is_empty())
            .map(PathBuf::from)
            .or_else(|| {
                get("HOME")
                    .filter(|s| !s.is_empty())
                    .map(|h| Path::new(&h).join(".local/state"))
            })?;
        Some(base.join("sliver/emoji-recents"))
    }

    pub fn items(&self) -> &[String] {
        &self.items
    }

    /// How `e` was last picked: the most recent use of it or one of its skin tones, else
    /// `e` itself. The picker shows and types this, so a chosen tone sticks.
    pub fn preferred(&self, e: &Emoji) -> String {
        if e.tones.is_some() {
            for r in &self.items {
                if family(r).is_some_and(|f| f.text == e.text) {
                    return r.clone();
                }
            }
        }
        e.text.to_string()
    }

    /// Use `text`: it moves to the front. Saved right away when persistent (a few bytes).
    pub fn push(&mut self, text: &str) {
        self.items.retain(|e| e != text);
        self.items.insert(0, text.to_string());
        self.items.truncate(MAX_RECENTS);
        if let Some(p) = &self.path {
            if let Some(dir) = p.parent() {
                let _ = std::fs::create_dir_all(dir);
            }
            let _ = std::fs::write(p, self.items.join("\n") + "\n");
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn data_is_complete_and_in_order() {
        let a = all();
        assert!(a.len() > 1800, "{}", a.len());
        assert_eq!(
            (a[0].text, a[0].name, a[0].group),
            ("😀", "grinning face", Group::Smileys)
        );
        for g in Group::ALL {
            assert!(in_group(g).count() > 50, "{g:?}");
        }
        assert!(
            a.iter().all(|e| !e.name.contains("skin tone")),
            "tone variants are excluded"
        );
        assert!(
            a.iter()
                .any(|e| e.text == "👨‍👩‍👧" || e.text.contains('\u{200d}')),
            "ZWJ sequences are there"
        );
        assert!(a.iter().any(|e| e.name == "flag: Japan"));
        // groups come in picker order: the first emoji of each group follows the previous group
        let firsts: Vec<Group> = Group::ALL.to_vec();
        let mut seen = Vec::new();
        for e in a {
            if seen.last() != Some(&e.group) {
                seen.push(e.group);
            }
        }
        assert_eq!(seen, firsts);
    }

    #[test]
    fn search_by_word_prefix() {
        let r = search("face tear", 10);
        assert!(
            r.iter().any(|e| e.name == "face with tears of joy"),
            "{:?}",
            r.iter().map(|e| e.name).collect::<Vec<_>>()
        );
        assert_eq!(search("  ", 5).len(), 0);
        assert_eq!(search("zzzzzz", 5).len(), 0);
        // an exact word ranks before a prefix match
        let r = search("cat", 5);
        assert!(r[0].name.split(' ').any(|w| w == "cat"), "{}", r[0].name);
        assert!(search("CAT", 3).len() == 3, "case-insensitive, limited");
    }

    #[test]
    fn recents_move_to_front_cap_and_persist() {
        let dir = std::env::temp_dir().join(format!("sliver-emoji-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let path = dir.join("state/emoji-recents");
        let mut r = Recents::at(&path);
        assert!(r.items().is_empty());
        r.push("😀");
        r.push("🔥");
        r.push("😀");
        assert_eq!(r.items(), ["😀", "🔥"]);
        for e in all().iter().take(40) {
            r.push(e.text);
        }
        assert_eq!(r.items().len(), MAX_RECENTS);
        let again = Recents::at(&path);
        assert_eq!(again.items(), r.items(), "reloaded from the file");
        let mem = Recents::new();
        assert!(mem.items().is_empty());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn state_path() {
        let p = Recents::default_path(|k| (k == "HOME").then(|| "/h".into())).unwrap();
        assert_eq!(p, Path::new("/h/.local/state/sliver/emoji-recents"));
        let p = Recents::default_path(|k| (k == "XDG_STATE_HOME").then(|| "/s".into())).unwrap();
        assert_eq!(p, Path::new("/s/sliver/emoji-recents"));
        assert!(Recents::default_path(|_| None).is_none());
    }

    #[test]
    fn skin_tones() {
        let thumbs = all().iter().find(|e| e.text == "👍").unwrap();
        assert_eq!(thumbs.tones.unwrap(), ["👍🏻", "👍🏼", "👍🏽", "👍🏾", "👍🏿"]);
        // ZWJ sequences: the tone goes on the person, not the end.
        let red = all().iter().find(|e| e.name == "man: red hair").unwrap();
        assert_eq!(red.tones.unwrap()[0], "👨🏻‍🦰");
        assert!(
            all()
                .iter()
                .find(|e| e.text == "😀")
                .unwrap()
                .tones
                .is_none()
        );
        assert!(all().iter().filter(|e| e.tones.is_some()).count() > 250);
        assert_eq!(family("👍🏾").unwrap().text, "👍");
        assert_eq!(family("👍").unwrap().text, "👍");
        assert!(family("not an emoji").is_none());

        // The last tone picked is the one shown next time; the plain one counts too.
        let mut r = Recents::new();
        assert_eq!(r.preferred(thumbs), "👍");
        r.push("👍🏽");
        r.push("😀");
        assert_eq!(r.preferred(thumbs), "👍🏽");
        r.push("👍");
        assert_eq!(r.preferred(thumbs), "👍");
    }
}
